{
  "decision-bank-clearing-exception-csv": "WITH totals AS (SELECT batch_ref, SUM(bank_cents) AS bank_total, 0 AS ledger_total FROM bank_lines GROUP BY batch_ref UNION ALL SELECT batch_ref, 0, SUM(ledger_cents) FROM clearing_lines GROUP BY batch_ref), differences AS (SELECT batch_ref, SUM(bank_total) - SUM(ledger_total) AS difference_cents FROM totals GROUP BY batch_ref) SELECT 'batch_ref,difference_cents' || char(10) || COALESCE(group_concat(record, ''), '') AS csv_contents FROM (SELECT batch_ref || ',' || difference_cents || char(10) AS record FROM differences WHERE difference_cents <> 0 ORDER BY batch_ref COLLATE BINARY)",
  "decision-bin-code-migration-matrix": "WITH codes(code, pos) AS (VALUES ('A', 1), ('B', 2), ('?', 3)), keys AS (SELECT bin_key FROM old_bins UNION SELECT bin_key FROM current_bins), counts AS (SELECT COALESCE(o.code, '?') AS old_code, COALESCE(c.code, '?') AS current_code, COUNT(*) AS bin_count FROM keys AS k LEFT JOIN old_bins AS o ON o.bin_key IS k.bin_key LEFT JOIN current_bins AS c ON c.bin_key IS k.bin_key GROUP BY COALESCE(o.code, '?'), COALESCE(c.code, '?')) SELECT a.code AS old_code, b.code AS current_code, COALESCE(n.bin_count, 0) AS bin_count FROM codes AS a CROSS JOIN codes AS b LEFT JOIN counts AS n ON n.old_code = a.code AND n.current_code = b.code ORDER BY a.pos, b.pos",
  "decision-book-a-coolant-exchange-stop": "SELECT r.depot_code, s.source_id, s.fee_cents, r.inbound_min + s.wait_min + r.outbound_min AS elapsed_min FROM route_sheet AS r JOIN signed_offer AS s ON s.depot_code = r.depot_code WHERE r.inbound_min + s.wait_min <= 100 AND r.outbound_min <= 90 AND r.inbound_min + s.wait_min + r.outbound_min <= 180 ORDER BY s.fee_cents, elapsed_min, r.depot_code COLLATE BINARY LIMIT 1",
  "decision-book-complementary-demo-packages": "WITH bookings(first_code, second_code, total_cents, forecast_signups) AS (SELECT package_code, NULL, fee_cents, signup_forecast FROM demo_packages UNION ALL SELECT a.package_code, b.package_code, a.fee_cents + b.fee_cents, a.signup_forecast + b.signup_forecast FROM demo_packages AS a JOIN demo_packages AS b ON a.package_code COLLATE BINARY < b.package_code AND a.territory <> b.territory) SELECT first_code, second_code, total_cents, forecast_signups FROM bookings WHERE total_cents <= 10000 ORDER BY forecast_signups DESC, total_cents, (second_code IS NOT NULL), first_code COLLATE BINARY, second_code COLLATE BINARY LIMIT 1"
}
